    /** Логотип рисуется в логических координатах устройства (520x350), как в SVG.
     *  transform="translate(10.79 238.92) rotate(-90) scale(0.17)". */
    fun draw(drawScope: DrawScope) {
        val p = PathParser().parsePathString(PATH).toPath()
        val g = SvgGeometry.Logo
        with(drawScope) {
            translate(g.Tx, g.Ty) {
                // pivot = origin: rotate/scale вокруг точки (0,0), а не центра холста
                rotate(g.RotationDeg, pivot = Offset.Zero) {
                    scale(g.Scale, g.Scale, pivot = Offset.Zero) {
                        drawPath(p, brush = SvgGradients.LogoMetal)
                    }
                }
            }
        }
    }

    @Composable
    fun View(modifier: Modifier = androidx.compose.ui.Modifier) {
        Canvas(modifier) { drawInDeviceSpace { draw(this) } }
    }
